WITH deduped AS (SELECT * FROM stores QUALIFY ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date DESC NULLS FIRST, id) = 1) SELECT CASE WHEN sqft >= 14207 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, DATE_TRUNC('YEAR', opened_date) AS year_start, COUNT(*) FILTER (WHERE city = 'Singapore') AS singapore_rows, SORT_ARRAY(COLLECT_SET(region)) AS region_list, PERCENTILE_APPROX(sqft, 0.95) AS sqft_p95, PERCENT_RANK() OVER (PARTITION BY CASE WHEN sqft >= 14207 THEN 'HIGH' ELSE 'LOW' END ORDER BY COUNT(*) FILTER (WHERE city = 'Singapore') DESC) AS singapore_rows_percent_rank FROM deduped GROUP BY 1, 2 ORDER BY singapore_rows DESC;
